      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Reported right-sided neck lump"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Present for maybe a year or two; patient thinks it has become somewhat larger over the last 6–12 months; not painful."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Reported symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Recently feels jittery, experiences heart flutters while sitting at her desk, feels hotter than others at work, and has lost approximately 3–4 kg without trying."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Reported negative symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No trouble swallowing or breathing, no voice change, no diarrhoea, and no obvious eye issues."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Thyroid examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Visible slight fullness of the right anterior neck; solitary approximately 3 cm firm, smooth, mobile, non-tender nodule in the right thyroid lobe; no obvious other thyromegaly and no palpable nodes."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Neurological examination findings"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Fine hand tremor; reflexes brisk but symmetrical."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Eye examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No exophthalmos."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Cardiovascular examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Heart sounds dual; mild tachycardia."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Chest examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Chest clear."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Thyroid-stimulating hormone (TSH)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "<0.01 mIU/L (low)"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Free thyroxine (FT4)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mildly elevated; exact number not available on summary screen."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Free triiodothyronine (FT3)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Elevated; numeric value not provided."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "TSH receptor antibody"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Negative."
      }
    },
