        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "Right thyroid lobe nodule measurement on ultrasound"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 32,
          "unit": "mm"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-19",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-19",
        "status": "final",
        "code": {
          "text": "Thyroid ultrasound nodule characteristics"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Right lobe nodule is solid, well circumscribed, mostly isoechoic, and has increased vascularity; no microcalcifications. Rest of thyroid appears suppressed."
      }
    },
